        {...gate.bind}

label="Auction sections"
        tabs={[
          { id: "squads", label: "Squads", content: <p>Four squads, sixty-four players.</p> },
          { id: "pool", label: "Pool", content: <p>Twelve players remain in the pool.</p> },
          { id: "purse", label: "Purse", content: <Money tone="remaining">₹1,24,00,000</Money> },
        ]}

variant="secondary"
          onClick={() => {
            toast({
              title: "Player saved",
              description: "Rohit S added to the pool.",
              tone: "success",
            });
          }}

variant="secondary"
          onClick={() => {
            toast({ title: "Connection lost", description: "Retrying…", tone: "danger" });
          }}

open={dialogOpen}
        onClose={() => {
          setDialogOpen(false);
        }}
        title="Remove player?"
        footer={
          <>
            <Button
              variant="secondary"
              onClick={() => {
                setDialogOpen(false);
              }}
            >
              Cancel
            </Button>
            <Button
              variant="danger"
              onClick={() => {
                setDialogOpen(false);
                toast({ title: "Player removed", tone: "info" });
              }}
            >
              Remove
            </Button>
          </>
        }

variant="danger"
              onClick={() => {
                setDialogOpen(false);
                toast({ title: "Player removed", tone: "info" });
              }}

variant="secondary"
          size="sm"
          onClick={() => {
            setTone("sold");
            setTake((value) => value + 1);
          }}

variant="secondary"
          size="sm"
          onClick={() => {
            setTone("unsold");
            setTake((value) => value + 1);
          }}

type="button"
                onClick={() => {
                  reset();
                }}
                style={{
                  ...link,
                  cursor: "pointer",
                  background: "#1c1b17",
                  color: "#faf8f2",
                  borderColor: "#1c1b17",
                  font: "inherit",
                  fontWeight: 600,
                }}

type="button"
        className="home-pin-button"
        aria-pressed={pinned}
        aria-label={pinned ? `Unpin ${competition.name}` : `Pin ${competition.name}`}
        onClick={() => {
          onTogglePin(competition.slug);
        }}

type="button"
          onClick={() => {
            window.location.reload();
          }}
          style={{
            ...button,
            border: "1px solid #f0b43c",
            background: "#f0b43c",
            color: "#1c1b17",
          }}

type="button"
          onClick={() => {
            setKind(null);
          }}
          style={{
            ...button,
            border: "1px solid rgba(250, 248, 242, 0.45)",
            background: "transparent",
            color: "#faf8f2",
          }}

id="newsletter-email"
              name="email"
              type="email"
              inputMode="email"
              required
              placeholder="you@example.com"
              autoComplete="email"
              className={styles["input"]}
              // Named, not merely printed: without the description the error is
              // rendered text a screen-reader user never hears, and
              // `aria-invalid` is how the field itself says it was rejected.
              aria-invalid={state.error !== undefined ? true : undefined}
              aria-describedby={describedBy}

key={chip.href + chip.label}
          href={chip.href}
          className="pk-chip"
          data-tone={chip.tone}
          data-active={chip.active === true ? "" : undefined}
          aria-current={chip.active === true ? "page" : undefined}

open
          onClose={onClose}
          title="Thanks — it's with the team"
          footer={
            <Button type="button" onClick={onClose}>
              Close
            </Button>
          }

id="report-description"
              name="description"
              rows={5}
              required
              minLength={5}
              maxLength={4000}
              className={styles["note"]}
              placeholder="What you did, what you expected, and what happened instead."
              aria-invalid={errorFor("description") !== undefined || undefined}
              aria-describedby={
                errorFor("description") !== undefined ? "report-description-error" : undefined
              }

label="Email for a reply (optional)"
            name="replyEmail"
            type="email"
            autoComplete="email"
            maxLength={254}
            defaultValue={defaultEmail ?? ""}
            help={
              signedIn
                ? "We'll only use it to reply about this report."
                : "Leave it blank and we can't write back to you."
            }
            error={errorFor("replyEmail")}

type="button"
            size="sm"
            variant="ghost"
            onClick={() => {
              onRemove({ state: "none", reason: "removed" });
            }}

type="file"
          accept="image/png,image/jpeg,image/webp"
          onChange={(event) => {
            const file = event.currentTarget.files?.[0];
            if (file === undefined) {
              return;
            }
            void shrinkImageFile(file).then((blob) => {
              if (blob === null) {
                onRemove({ state: "none", reason: "rejected" });
              } else {
                onAdopt(blob, "file");
              }
            });
          }}

className="shell-icon-button shell-bell"
      href="/inbox"
      aria-label={unread ? `Notifications — ${label} new` : "Notifications"}
      data-testid="shell-bell"
      data-unread={unread}
      data-count={unread ? unreadCount : 0}

type="button"
                className="shell-icon-button shell-mobile-only"
                aria-label="Menu"
                onClick={() => {
                  setDrawerOpenOn(pathname);
                }}

type="button"
                    className="shell-drawer-link"
                    data-testid="drawer-install-app"
                    onClick={() => {
                      setDrawerOpenOn(null);
                      openInstall("drawer");
                    }}

type="button"
                  className="shell-drawer-link"
                  onClick={() => {
                    // Close the drawer first: the screenshot is of the page,
                    // not of the menu that was covering it.
                    setDrawerOpenOn(null);
                    reportProblem();
                  }}

type="button"
                  className="shell-drawer-link shell-drawer-danger"
                  onClick={() => void scoringSignOut(logout)}

type="button"
        className="shell-season-chip"
        aria-label={`Season: ${current.name}, ${current.orgName}. Change season`}
        aria-haspopup="dialog"
        onClick={() => {
          setOpen(true);
        }}
        data-testid="season-chip"

open
          side="bottom"
          title="Switch season"
          onClose={() => {
            setOpen(false);
          }}
          className="shell-season-sheet"

href={`/seasons/${season.slug}`}
                        className="shell-season-row"
                        aria-current={season.slug === current.slug ? "page" : undefined}
                        onClick={() => {
                          setOpen(false);
                        }}

className="shell-social-link"
            data-network={account.network}
            href={account.href}
            target="_blank"
            rel="noopener me"
            aria-label={`DesiAuction on ${account.label}`}

type="button"
      className={className}
      data-testid="sound-toggle"
      aria-pressed={sound.enabled}
      aria-label={label}
      title={sound.enabled ? "Sound on" : "Sound off"}
      onClick={() => {
        void sound.setEnabled(!sound.enabled);
      }}

type="button"
      className={variant === "row" ? "shell-drawer-link shell-theme-row" : "shell-icon-button"}
      data-testid={variant === "row" ? "theme-toggle-row" : "theme-toggle"}
      {...(variant === "icon"
        ? {
            "aria-label": next === "floodlight" ? "Switch to dark theme" : "Switch to light theme",
            title: next === "floodlight" ? "Dark" : "Light",
          }
        : {})}
      onClick={() => {
        document.documentElement.setAttribute("data-theme", next);
        try {
          window.localStorage.setItem(THEME_STORAGE_KEY, next);
        } catch {
          // Private mode / storage disabled: the switch still works for this view.
        }
      }}

