              label={`${squad.teamName} ${field.label.toLowerCase()}`}
              name={`${squad.teamId}-${field.key}`}
              inputMode="numeric"
              {...(field.help !== undefined ? { help: field.help } : {})}
              value={places[squad.teamId]?.score[field.key] ?? ""}
