            const kind = event.target.value as WicketKind | "";
            setPayload((previous) => {
              const rest = { ...previous };
              delete rest.wicket;
              return {
                ...rest,
                ...(kind
                  ? {
                      wicket: {
                        kind,
                        playerOutId: previous.wicket?.playerOutId ?? previous.strikerId,
                        fielderIds:
                          kind === "caught_and_bowled"
                            ? [previous.bowlerId]
                            : (previous.wicket?.fielderIds ?? []),
