                label: STAGE_LABEL[key],
                count: formatCount(stageCounts.get(key) ?? 0),
                active: stage === key,
                onSelect: () => {
                  setStage(stage === key ? "all" : key);
                },
                testId: `tg-status-${key}`,
              })),
            ]}

