              onRemove({ state: "none", reason: "removed" });
            }}

type="file"
          accept="image/png,image/jpeg,image/webp"
          onChange={(event) => {
            const file = event.currentTarget.files?.[0];
            if (file === undefined) {
              return;
            }
            void shrinkImageFile(file).then((blob) => {
              if (blob === null) {
                onRemove({ state: "none", reason: "rejected" });
              } else {
                onAdopt(blob, "file");
              }
            });
          }}

